// Validate booking payload and guard against duplicate event IDs
const data = items[0].json;
if (!data.bookingReference || !data.userEmail) {
  throw new Error('Invalid booking payload: reference and userEmail required');
}

return [{
  json: {
    bookingId: data.bookingId,
    bookingReference: data.bookingReference,
    type: data.type,
    propertyTitle: data.propertyTitle,
    propertyLocation: data.propertyLocation,
    plotUnit: data.plotUnit || 'Selected Plot',
    plotAreaSqFt: data.plotAreaSqFt,
    priceFormatted: data.priceFormatted,
    userName: data.userName,
    userEmail: data.userEmail,
    userPhone: data.userPhone,
    siteVisitDate: data.siteVisitDate,
    siteVisitTime: data.siteVisitTime,
    status: data.bookingStatus || 'Pending',
    adminEmail: 'admin@llb.com',
    adminDashboardUrl: data.adminDashboardUrl,
    submittedAt: data.submittedAt || new Date().toISOString()
  }
}];
